contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // params: minSum to set, depositAmt to deposit, collectAmt to attempt to collect
    function run(uint minSum, uint depositAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // ensure this test contract can fund the deposit
        require(address(this).balance >= depositAmt);

        // initialize MinSum and LogFile (must be done before Initialized() if ever called)
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(c)); if (__ESBMC_reverted()) return;

        // Deposit depositAmt into c from this contract
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // record stored balance before Collect and contract balance of c
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool didRevert;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // record stored balance after and contract balance after
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        // General invariant: if Collect did not revert then stored balance cannot increase
        // and the contract's Ether balance cannot have increased (Collect only can transfer out or do nothing)
        assert(didRevert || (balAfter <= balBefore && cBalAfter <= cBalBefore));
    }

    receive() external payable { }
}

